import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    r = int(data[2]) - 1
    c = int(data[3]) - 1
    x = int(data[4])
    y = int(data[5])

    labyrinth = [data[i + 6] for i in range(n)]

    # Initialize a 3D DP array to keep track of reachable cells
    dp = [[[False] * (m + 1) for _ in range(n)] for _ in range(x + y + 1)]

    # Starting point
    dp[0][r][c] = True

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Fill the DP table
    for k in range(x + y + 1):
        for i in range(n):
            for j in range(m):
                if dp[k][i][j]:
                    for dr, dc in directions:
                        ni, nj = i + dr, j + dc
                        if 0 <= ni < n and 0 <= nj < m and labyrinth[ni][nj] == '.':
                            nk = k
                            if dr == 0:
                                if dc == -1:
                                    nk = min(k + 1, x + y)
                                elif dc == 1:
                                    nk = min(k + 1, x + y)
                            if nk <= x + y:
                                dp[nk][ni][nj] = True

    # Count the number of reachable cells
    count = sum(dp[k][i][j] for k in range(x + y + 1) for i in range(n) for j in range(m))

    print(count)

if __name__ == "__main__":
    main()
